"use strict";(self.webpackChunkzerroo=self.webpackChunkzerroo||[]).push([[6807],{14308:(e,n,t)=>{t.d(n,{Z:()=>m});var r=t(15491),o=t(20890),i=t(89673),s=t(3721),a=t(55818),c=t(66934),l=t(72791),d=t(80184);const p=(0,c.ZP)((e=>(0,d.jsx)(i.Z,{disableGutters:!0,elevation:0,square:!0,...e})))((e=>{let{theme:n}=e;return{marginBottom:n.spacing(2),"&:not(:last-child)":{borderBottom:0},"&:before":{display:"none"}}})),h=(0,c.ZP)((e=>(0,d.jsx)(a.Z,{expandIcon:(0,d.jsx)(r.Z,{}),...e})))((e=>{let{theme:n}=e;return{padding:n.spacing(2),backgroundColor:"#f9f9f9",flexDirection:"row","& .MuiAccordionSummary-expandIconWrapper.Mui-expanded":{transform:"rotate(90deg)"}}})),u=(0,c.ZP)(s.Z)((e=>{let{theme:n}=e;return{padding:n.spacing(2)}}));function m(e){let{faqs:n}=e;const[t,r]=(0,l.useState)(0);return n.map(((e,n)=>{let{question:i,answer:s}=e;return(0,d.jsxs)(p,{expanded:t===n,onChange:(a=n,(e,n)=>{r(!!n&&a)}),children:[(0,d.jsx)(h,{"aria-controls":`${n}-content`,id:`${n}-header`,children:(0,d.jsx)(o.Z,{mr:1,variant:"h5",color:"brand",children:i})}),(0,d.jsx)(u,{children:(0,d.jsx)(o.Z,{variant:"body2",textAlign:"justify",dangerouslySetInnerHTML:{__html:s}})})]},n);var a}))}},46807:(e,n,t)=>{t.r(n),t.d(n,{default:()=>a});var r=t(89164),o=t(20890),i=(t(72791),t(14308)),s=t(80184);function a(){return(0,s.jsxs)(r.Z,{sx:{my:4},children:[(0,s.jsx)(o.Z,{variant:"h1",mb:4,children:"Commonly used terms in Direct selling"}),(0,s.jsx)(i.Z,{faqs:[{question:"Customer",answer:"\u201cCustomer\u201d refers to any person/s whether an individual or an organisation (a group of individuals) who:\n<br></br>Buys any goods for a consideration which has been paid or promised or partly paid and partly promised, or under any system of deferred payment who may be a user/consumer includes any user of such goods other than the person who buys such goods for consideration paid or promised or partly paid or partly promised, or under any system of deferred payment when such use is made with the approval of such person, but does not include a person who obtains such goods for resale.\n<br></br>Or\n<br></br>Hires or avails of any services for a consideration which has been paid or promised or partly paid and partly promised, or under any system of deferred payment and includes any beneficiary of such services other than the person who hires or avails of the services for consideration paid or promised, or partly paid and partly promised, or under any system of deferred payment, when such services are availed of with the approval of the first-mentioned person but does not include a person who avails of such services for providing it to another person/s."},{question:"Explanation \u2013 for this clause",answer:'a.\u201ccommercial purpose\u201d does not include use by a person who purchases the goods or services to use/consumes them, but the goods or services are purchased exclusively to earn his livelihood using self-employment.\n<br></br> b.The expressions \u201cbuys any goods\u201d and hires or avails any services include offline and/online transactions through electronic means or by teleshopping or direct selling deploying direct, single-level or multi-level marketing compensation plan.\n<br></br>The "customer" may or may not be a direct seller.\n<br></br>A customer may or may not be a consumer.\n(with inputs from the Consumer Protection Act, 2019)\n'},{question:"Direct Selling",answer:"\u201cDirect selling\u201d means marketing, distribution, and sale of goods or provision of services through a network of persons (registered with the company as independent contractors), other than through a permanent retail location/s.\n<br></br>It Is primarily a B2C (Business to Customer) model with some exceptions (where the agreement is entered into between the Direct selling entity and an Entity / Organisation- Proprietary, Partnership, Limited liability Partnership, One-person company / Private limited company, Trust, Public limited company, etc.)\n<br></br>Also known as Direct Sales, Network marketing, Referral marketing, Affiliate marketing, etc.\n "},{question:"Company Literature",answer:"\u201cCompany Literature\u201d refers to any documents in physical or in electronic form including business opportunity materials, product catalogues, brochures, newsletters, emails, etc. issued or published by the Company on their official platforms to share information, spread awareness, etc."},{question:"Direct Selling Entity",answer:"\u201cDirect Selling Entity\u201d, means a body corporate which may be a One-person company or a Limited liability partnership or a private limited company engaged in the business of Direct Selling.\n<br></br>The organisation may be a manufacturer or a trader of the product/s and/or services.\n<br></br>It utilises the services of persons who are independent contractors, also known as direct sellers, to recommend and retail product/s and /or services.\n<br></br>The company may commit, calculate and pay incentives/commissions to the direct sellers by deploying Direct, Single level or a Multi-level marketing compensation plan/s."},{question:"Independent Contractor",answer:"An Independent Contractor is a person who signs a contract for service* with the entity.\n<br></br>A contract for service* implies an agreement wherein one party undertakes to provide services, to or for another in the performance of which he is not subject to detailed direction and control but exercises professional or technical skill and uses his knowledge and discretion.\n<br></br>A direct seller/participant Is an independent contractor.\n"},{question:"Direct seller",answer:"\u201cDirect Seller\u201d is a person above the age of 18 years on the date of enrolment with eligibility to enter into a business contract* who enrols/registers/signs up with the direct selling entity through a legally enforceable agreement (as an \u201cindependent contractor\u201d) to undertake direct selling business on principal to principal basis for purchasing the goods at a discount for self-consumption and/or an opportunity to earn income by retailing goods and/or by helping others enrol and retail the goods.\n<br></br>A direct seller may be a consumer/user or a customer/purchaser/buyer or a reseller or all of the three.\n<br></br>Direct Sellers are generally also known as Distributors, Associates, Independent business owners, Consultants, Networkers, Members, Advisors, Independent business associates, Affiliates, Independent representatives, Agents, etc.\n<br></br>*Explanation: - A \u2018contract\u2019 includes e-contracts or digital contracts and the same shall be governed as per the provisions of the Information Technology Act, 2000 and Indian Contract Act as amended from time to time."},{question:"Prospect & Prospective",answer:"\u201cProspect\u201d means a person to whom an offer or a proposal is made by the Direct Seller to join a Direct Selling business opportunity or to purchase a product/service."},{question:"Goods",answer:"The term \u201cgoods\u201d refers to movable property and includes anything, products or services, tangible or intangible that constitutes the subject of a proposed transaction."},{question:"Saleable",answer:"\u201cSaleable\u201d concerning goods or services means unopened, unused, marketable and of merchantable quality, which has not expired, and which is not discontinued or goods or services of special promotion/s or the ones offered free or at a token price.\n"},{question:"Service",answer:"Service means service of any description which is made available to potential users and includes, but not limited to, the provision of facilities in connection with banking, financing, insurance, transport, processing, the supply of electrical or other energy, telecom, boarding or lodging or both, housing construction, entertainment, amusement or the purveying of news or additional information but does not include the rendering of any service free of charge or under a contract of personal service."},{question:"Price",answer:"Service means service of any description which is made available to potential users and includes, but not limited to, the provision of facilities in connection with banking, financing, insurance, transport, processing, the supply of electrical or other energy, telecom, boarding or lodging or both, housing construction, entertainment, amusement or the purveying of news or additional information but does not include the rendering of any service free of charge or under a contract of personal service."},{question:"Purchase",answer:"\u201cPurchase\u201d means the acquisition of goods/service against a price."},{question:"Person",answer:"\u201cPerson\u201d, unless otherwise provided, will mean a person as per the Consumer Protection Act, 2019."},{question:"Quality",answer:"\u201cQuality\u201d is the ability to perform satisfactorily in service and is suitable for its intended purpose as indicated in the official literature/application/website including brochures, labels, and presentations developed/distributed/retailed by the company. Quality of goods/services includes their state or condition.\nThis policy is to address the quality issues of the good/s."},{question:"Money Back Guarantee",answer:"\u201cMoney back guarantee\u201d is the promise to the persons associated with the company and the customers to empower them to return the goods If they are unable to retail the purchased product/s to the customer/s alternatively, unable to use them for self-consumption.\nThis policy is to address the concerns of the overstocking of products by the persons (direct sellers/independent contractors) engaged in direct selling. It also builds good faith between the parties and helps minimise the wastage of resources."},{question:"Negative Product List",answer:"\u201cNegative product list\u201d is the list of goods which are not to be promoted by the company."},{question:"Special Product List",answer:"\u201cSpecial product list\u201d is the list of products/services which may be promoted following the conditions mentioned along with them."},{question:"Official Communication",answer:"\u201cOfficial communication\u201d shall refer to any communication made by the entity or its authorised personnel in written form (printed or in electronic form on the domains/application owned and/or operated by the entity)."},{question:"Delivery",answer:"\u201cDelivery\u201d is a voluntary transfer of possession/s from one party to another."},{question:"Office",answer:"\u201c\u201cOffice\u201d means a room, set of rooms, or building used as a place of exclusively conducting business activities as mentioned on the official literature/website/application of the entity."},{question:"Enrol",answer:"\u201cEnrol\u201d means to introduce/register/signup formally through a legally enforceable contract (as per the latest version of the Indian Contract Act and IT Act) for undertaking the business on principal to principal basis as a participant or a person or any entity including any names mentioned under the definition of a direct seller."},{question:"Organization Structure",answer:"\u201cOrganization Structure\u201d is the way of representing the tiered nature of persons in a graphical form to help them recognize their relative positions to the company or the persons above or below them.\n <br></br>This arrangement is also known as the Tree structure or Network Structure."},{question:"Types of Organization Structures",answer:"<b>a.Types of frontline (or leg) structures (the maximum number of participants that can be arranged in the frontline)</b>\n<br></br>Participants mapped directly with the Participant in his/her Organisation Structure are known as the frontline.\n<br></br>1.<b>Binary</b> \u2013 Maximum two persons in the frontline\n\n<br></br><b>b.Types of Generation (or Level) Structures (of participant/s)</b>\n\n<br></br>A company may choose to have the participants (independent contractors) structured in a  Multi-level structure/s. It is completely influenced by the compensation plan of the company.\n<br>Generation is commonly referred to as a level.\n<br></br>1.<b>Multi-level</b> \u2013 The participants are connected to the company via another participant/s arranged in more than a single level all having existing contractual relationships with the company"},{question:"Compensation Plan",answer:"\u201cCompensation plan\u201d is a technique to calculate the returns/commissions/incentives and/or the rewards assured/promised to be given to/among participant/s from the money invested/turnover from the sales of goods/provision of services directly/indirectly provided by them personally or by other participants in their organisation structure.\n                    <br></br>The Compensation plans are developed to encourage and reward various behaviours \u2013 Personal purchase for self-consumption or retail, and/or supporting the participants in the Organisation Structure for retailing, enrolling participants (though offering compensation on conscription of persons is an unethical practice), etc.\n<br></br>This is also known as Remuneration system.\n"},{question:"Types of compensation plans",answer:"<b>a.Paid on Generation/s:</b>\n<br></br><b>Multiple</b> \u2013 The participants using/consuming or selling the goods get an opportunity to be compensated on their purchases/retail and the purchases/retail by persons in more than the first generation. This type of compensation plan is usually deployed by companies having persons arranged in multiple levels or Multi-level marketing organisation structure.\n\n                    <br></br><b>b.Rank/ Title achievement:</b>\n<br></b><b>Non-cumulative</b> \u2013 Participants, regardless of their ranks/titles in the previous month, start a new calendar month with the same levels/ranks/ titles. The sales counter starts with zero every month.\n<br></b><b>Cumulative</b> \u2013 On achievement of any ranks/titles, the participants continue to enjoy the privileges meant for the highest rank attained although their association with the company while the earning is calculated on the sales for that specific period.\n\n<br></br><b>c.The frequency of Compensation Pay-outs:</b>\n<br></b><b>Weekly</b> \u2013 Pay-out is calculated and disbursed weekly"},{question:"Direct Marketing",answer:"\u201cDirect marketing\u201d is a method in which companies communicate directly with prospects through formats like online advertisements, direct mailing (postal mail and email), text messaging and voice calls."},{question:"Ecommerce",answer:"\u201cE-commerce\u201d is the display and/or the sale and/or purchase of goods & services conducted using the digital or an electronic network including but not limited to the world wide web."},{question:"Electronic Service Provider",answer:"Electronic service provider means a person/entity who provides technologies or processes to enable a product seller to engage in advertising or selling goods or services to a consumer and includes any online marketplace or online auction sites."},{question:"Prevailing Laws",answer:"\u201cPrevailing Laws\u201d means all provisions of the applicable Acts, Rules, Regulations, Notifications, Guidelines, Circulars, Ordinances, Orders, Advisories, Clarifications, etc., including any amendments therein or enactment thereof, for the time being in force."}]})]})}}}]);
